(()=>{'use strict';
const VERSION='20260728-passages-wb-v3';
const ROUTES=`player-data/routes.json?v=${VERSION}`;const ALIASES=`player-data/aliases.json?v=${VERSION}`;
const CURRENT_STATS=`ffws-br-2026-s2/player-stats.json?v=${VERSION}`;
const root=document.getElementById('player-root');
const params=new URLSearchParams(location.search);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/gi,'').toLowerCase();
const num=v=>Number(v)||0;
const fmt=v=>num(v).toLocaleString('pt-BR');
const avg=(a,b)=>b?(num(a)/num(b)).toFixed(2):'0.00';
const cache=new Map();
async function getJSON(url){if(cache.has(url))return cache.get(url);const p=fetch(url,{cache:'default'}).then(r=>{if(!r.ok)throw new Error(`Falha ao carregar ${url.split('?')[0]}`);return r.json()});cache.set(url,p);return p}
function stat(label,value,sub='',rank='',attr=''){return`<div class="stat-card"${attr?` ${attr}`:''}><small>${esc(label)}</small><strong>${esc(value)}</strong>${sub?`<span>${esc(sub)}</span>`:''}${rank?`<span class="rank-pill">#${esc(rank)}</span>`:''}</div>`}
function titleStat(label,type){return stat(label,'—','Carregando registros','','data-title-'+type)}
function editionRow(e){return`<div class="edition-row"><div><strong>${esc(e.edition||e.name||'Edição')}</strong><small>${esc(e.team||e.status||'')}</small></div><div class="edition-stat"><b>${fmt(e.kills)}</b><span>Abates</span></div><div class="edition-stat"><b>${fmt(e.matches)}</b><span>Quedas</span></div><div class="edition-stat"><b>${Number(e.avg??(e.matches?num(e.kills)/num(e.matches):0)).toFixed(2)}</b><span>Média</span></div><div class="edition-stat"><b>${e.damage?fmt(e.damage):'—'}</b><span>Dano</span></div></div>`}
function teamCard(e){return`<div class="team-history-card"><img src="${esc(e.logo||'escudo.webp')}" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='escudo.webp'" alt=""><div><strong>${esc(e.team||'Equipe')}</strong><small>${esc(e.edition||e.cargo||'')}</small></div></div>`}
function stageRows(stages={}){const labels={groups:'Fase de Grupos',classificatoria:'Classificatória',survival:'Repescagem',repescagem:'Repescagem',final:'Final','fase2-dia1':'Fase 2 · Dia 1','fase2-dia2':'Fase 2 · Dia 2','fase2-dia3':'Fase 2 · Dia 3','fase2-dia4':'Fase 2 · Dia 4','last-chance':'Última Chance'};const rows=Object.entries(stages||{});if(!rows.length)return'';return`<div class="stage-list">${rows.map(([key,s])=>`<div class="stage-row"><strong>${esc(labels[key]||key)}</strong><span>${fmt(s.kills)} K</span><span>${fmt(s.matches)} Q</span><span>${s.matches?avg(s.kills,s.matches):'0.00'} K/Q</span>${s.damage!=null?`<span>${fmt(s.damage)} dano</span>`:''}</div>`).join('')}</div>`}
function competitionSection(c){return`<section class="profile-section"><div class="profile-section-head"><h2>${esc(c.name)}</h2><p>${esc(c.team||'')}</p></div><div class="stats-grid basic-stats">${stat('Abates',fmt(c.kills),`Média: ${avg(c.kills,c.matches)} /queda`)}${stat('Dano',c.damage?fmt(c.damage):'—',c.damage?`Média: ${avg(c.damage,c.matches)} /queda`:'Sem registro')}${stat('Assistências',c.assists?fmt(c.assists):'—',c.assists?`Média: ${avg(c.assists,c.matches)} /queda`:'Sem registro')}${stat('Quedas',fmt(c.matches))}${stat('MVPs',fmt(c.mvp||0))}</div>${stageRows(c.stages)}</section>`}
function hero(p,type){const roster=p.currentRoster||{};const status=type==='full'?'JOGADOR DA WB 2026 S2':type==='historical'?'PERFIL HISTÓRICO':'PERFIL COMPETITIVO';const team=p.currentTeam||p.lastTeam||'';const logo=p.currentTeamLogo||p.lastTeamLogo||'escudo.webp';const badges=[roster.captain?'<span class="profile-badge gold">Capitão</span>':'',roster.rookie?'<span class="profile-badge">Estreante na WB 2026 S2</span>':'',roster.starter?'<span class="profile-badge">Titular</span>':roster.rosterStatus?`<span class="profile-badge">${esc(roster.rosterStatus)}</span>`:''].join('');return`<section class="profile-hero profile-${type}"><div class="profile-photo-wrap"><img class="profile-photo" src="${esc(p.photo||'silhueta.webp')}" decoding="async" onerror="this.onerror=null;this.src='silhueta.webp'" alt="${esc(p.name)}">${team?`<img class="profile-team-logo" src="${esc(logo)}" decoding="async" onerror="this.onerror=null;this.src='escudo.webp'" alt="${esc(team)}">`:''}</div><div><div class="profile-kicker">${status}</div><h1 class="profile-name">${esc(p.name)}</h1>${team?`<a class="profile-team" href="equipe.html?time=${encodeURIComponent(team)}">${esc(team)}</a>`:''}<div class="profile-meta">${esc(p.role||roster.role||'Jogador')}${roster.fullName?` • ${esc(roster.fullName)}`:''}${roster.state?` • ${esc(roster.state)}`:''}</div><div class="profile-badges">${badges}</div></div></section>`}
function allTimeSection(p,includeTitles=true){const a=p.allTime||{};return`<section class="profile-section"><div class="profile-section-head"><h2>Desempenho histórico — All-Time</h2><p>Competições registradas no site</p></div><div class="stats-grid historical-grid${includeTitles?'':' compact-history'}">${stat('Kills históricas',fmt(a.kills))}${stat('Quedas jogadas',fmt(a.matches))}${stat('Média histórica',Number(a.avg??(a.matches?num(a.kills)/num(a.matches):0)).toFixed(2))}${includeTitles?titleStat('Títulos coletivos','collective')+titleStat('Títulos individuais','individual'):''}</div></section>`}
function histories(p){const editions=(p.editions||[]).filter(e=>num(e.kills)||num(e.matches)||e.status);const teams=p.teamHistory||[];return`${editions.length?`<section class="profile-section"><div class="profile-section-head"><h2>Histórico por edições</h2><p>Resultados cadastrados</p></div><div class="edition-list">${editions.slice().reverse().map(editionRow).join('')}</div></section>`:''}<section class="profile-section"><div class="profile-section-head"><h2>Passagens por equipes</h2><p>Da primeira à organização mais recente</p></div><div class="team-history-list" id="profile-team-history">${teams.map(teamCard).join('')||'<div class="season-empty">Histórico de equipes em atualização.</div>'}</div></section><section class="profile-section" id="profile-trophies-section" hidden><div class="profile-section-head"><h2>Galeria de títulos</h2></div><div class="trophy-grid" id="profile-trophies"></div></section>`}
function fullRender(p,s2){const latest=p.ffws||null;const current={...(p.s2||{}),...(s2||{})};const currentHas=num(current.matches)>0;const competitions=(p.competitions||[]).filter(c=>c.key!=='ffws-br-2026-s2');root.innerHTML=hero(p,'full')+`<section class="profile-section"><div class="profile-section-head"><h2>Desempenho atual — WB 2026 S2</h2><p>${currentHas?'Temporada em andamento':'Temporada ainda não iniciada'}</p></div><div class="stats-grid current-grid">${stat('Abates totais',fmt(current.kills),`Média: ${avg(current.kills,current.matches)} /queda`,current.rankKills)}${stat('Dano total',fmt(current.damage),`Média: ${avg(current.damage,current.matches)} /queda`,current.rankDamage)}${stat('Assistências',fmt(current.assists),`Média: ${avg(current.assists,current.matches)} /queda`,current.rankAssists)}${stat('Quedas jogadas',fmt(current.matches))}${stat('Recorde de abates',fmt(current.record||0),'Em uma única queda/dia')}${stat('MVPs recebidos',fmt(current.mvp))}</div>${!currentHas?'<div class="season-empty">As estatísticas da temporada aparecerão aqui após as primeiras quedas.</div>':''}</section>`+(latest?`<section class="profile-section"><div class="profile-section-head"><h2>WB 2026 S1</h2><p>${esc(latest.team||'Última edição concluída')}</p></div><div class="stats-grid">${stat('Abates totais',fmt(latest.kills),`Média: ${avg(latest.kills,latest.matches)} /queda`,latest.rankKills)}${stat('Dano total',fmt(latest.damage),`Média: ${avg(latest.damage,latest.matches)} /queda`,latest.rankDamage)}${stat('Assistências',fmt(latest.assists),`Média: ${avg(latest.assists,latest.matches)} /queda`,latest.rankAssists)}${stat('Quedas jogadas',fmt(latest.matches))}${stat('Recorde de abates',fmt(latest.record),'Em um único dia')}${stat('MVPs recebidos',fmt(latest.mvp))}</div></section>`:'')+competitions.map(competitionSection).join('')+allTimeSection(p)+histories(p)}
function basicRender(p){root.innerHTML=hero(p,'basic')+(p.competitions||[]).map(competitionSection).join('')+allTimeSection(p,false)+histories(p)}
function historicalRender(p){root.innerHTML=hero(p,'historical')+allTimeSection(p)+histories(p)}
function decodeRoute(id,code){if(!code)return null;if(code.startsWith('s:'))return{id,profileType:'full',source:`player-data/s2/${code.slice(2)}.json`};if(code==='e')return{id,profileType:'basic',source:'player-data/basic/ewc-2026.json'};if(code==='l')return{id,profileType:'basic',source:'player-data/basic/laff-2026-s1.json'};if(code==='a')return{id,profileType:'basic',source:'player-data/basic/ffws-sea-2026.json'};if(code==='h')return{id,profileType:'historical',source:'player-data/historical.json'};return null}async function resolveRoute(){const routeMap=await getJSON(ROUTES);const direct=params.get('id');if(direct&&routeMap.routes?.[direct])return decodeRoute(direct,routeMap.routes[direct]);const wanted=params.get('jogador')||params.get('player')||'';const team=params.get('time')||params.get('team')||'';if(!wanted)return null;const idx=await getJSON(ALIASES),wk=norm(wanted),tk=norm(team);const matches=(idx.players||[]).filter(p=>norm(p.name)===wk||(p.aliases||[]).some(a=>norm(a)===wk));let found=null;if(tk)found=matches.find(p=>norm(p.team)===tk||((tk==='loud'||tk==='loudsnickers')&&['loud','loudsnickers'].includes(norm(p.team))));found=found||matches[0];return found&&routeMap.routes?.[found.id]?{...found,...decodeRoute(found.id,routeMap.routes[found.id])}:null}
async function loadProfile(route){const source=await getJSON(`${route.source}?v=${VERSION}`);const p=source.players?.[route.id];if(!p)throw new Error('Perfil não encontrado');if(route.profileType==='full'){let current={};try{const s=await getJSON(CURRENT_STATS);current=s.players?.[route.id]||{}}catch{}return{p,current}}return{p,current:null}}
function aliasesFor(p){return [p.name,...(p.aliases||[])].map(norm).filter(Boolean)}
function tsvRows(text){return String(text||'').replace(/\r/g,'').split('\n').filter(Boolean).map(r=>r.split('\t'))}
async function cachedText(key,url,ttl=1800000){try{const raw=localStorage.getItem(key);if(raw){const c=JSON.parse(raw);if(Date.now()-c.time<ttl)return c.text}}catch{}const r=await fetch(url,{cache:'default'});if(!r.ok)throw new Error('Fonte indisponível');const text=await r.text();try{localStorage.setItem(key,JSON.stringify({time:Date.now(),text}))}catch{}return text}
function updateTitleCards(collective,individual){document.querySelectorAll('[data-title-collective] strong').forEach(e=>e.textContent=String(collective.length));document.querySelectorAll('[data-title-individual] strong').forEach(e=>e.textContent=String(individual.length));document.querySelectorAll('[data-title-collective] span').forEach(e=>e.textContent='Conquistas registradas');document.querySelectorAll('[data-title-individual] span').forEach(e=>e.textContent='Prêmios registrados');const box=document.getElementById('profile-trophies'),sec=document.getElementById('profile-trophies-section');const rows=[...collective.map(x=>({...x,kind:'Coletivo'})),...individual.map(x=>({...x,kind:'Individual'}))];if(box&&sec&&rows.length){sec.hidden=false;box.innerHTML=rows.map(x=>`<div class="trophy-card"><span>🏆</span><div><strong>${esc(x.event||'Título')}</strong><small>${esc(x.type||x.kind)}${x.team?` • ${esc(x.team)}`:''}</small></div></div>`).join('')}}
async function loadTitles(p){const cfg=window.CFF_CONFIG?.sheets;if(!cfg)return;const aliases=aliasesFor(p);try{const [ct,it]=await Promise.all([cachedText('cff-player-titles-collective',cfg.recordesColetivos),cachedText('cff-player-titles-individual',cfg.recordesIndividuais)]);const collective=tsvRows(ct).slice(1).map(r=>({event:r[0]?.trim(),type:r[1]?.trim(),team:r[2]?.trim(),players:(r[3]||'').split(',').map(s=>s.trim())})).filter(x=>x.event&&x.players.some(n=>aliases.includes(norm(n))));const individual=tsvRows(it).slice(1).map(r=>({event:r[0]?.trim(),type:r[1]?.trim(),team:r[2]?.trim(),player:r[3]?.trim()})).filter(x=>x.event&&aliases.includes(norm(x.player)));updateTitleCards(collective,individual)}catch{document.querySelectorAll('[data-title-collective] strong,[data-title-individual] strong').forEach(e=>e.textContent='—');document.querySelectorAll('[data-title-collective] span,[data-title-individual] span').forEach(e=>e.textContent='Registro indisponível') }}
async function boot(){try{const route=await resolveRoute();if(!route)throw new Error('Jogador não encontrado');const {p,current}=await loadProfile(route);document.title=`${p.name} | Central Free Fire`;if(route.profileType==='full')fullRender(p,current);else if(route.profileType==='basic')basicRender(p);else historicalRender(p);if(route.profileType!=='basic'){const secondary=()=>{loadTitles(p)};if('requestIdleCallback'in window)requestIdleCallback(secondary,{timeout:2500});else setTimeout(secondary,500)}}catch(e){root.innerHTML=`<div class="player-error"><strong>${esc(e.message||'Não foi possível abrir o perfil.')}</strong><a class="player-back" href="index.html">Voltar para a página inicial</a></div>`}}
boot();
})();
